1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	/**
59	 * A fractional amount is always rounded in the MHPCO's favour, once, at the end
60	 * of the calculation it concludes. Which direction that is depends on who pays:
61	 * the customer pays a premium, so it rounds up; the MHPCO pays a claim, so it
62	 * rounds down. Intermediate amounts stay fractional.
63	 */
64	const roundPremiumInMHPCOsFavour = Math.ceil;
65	const roundPayoutInMHPCOsFavour = Math.floor;
66	
67	const BASE_PREMIUMS: Record<string, number> = {
68	  sword: 100,
69	  amulet: 60,
70	  staff: 80,
71	  potion: 40,
72	  rune: 25,
73	  moonstone: 25,
74	};
75	
76	/** Components are the small parts — runes, moonstones — as opposed to main items. */
77	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
78	
79	/** The block discount is a components-only offer. */
80	const ALIKE_ITEMS_BLOCK = { size: 3, basePremium: 60 };
81	
82	const formsBlock = (type: string, count: number): boolean =>
83	  COMPONENT_TYPES.has(type) && count === ALIKE_ITEMS_BLOCK.size;
84	
85	const basePremiumForItemType = (type: string, count: number): number =>
86	  formsBlock(type, count)
87	    ? ALIKE_ITEMS_BLOCK.basePremium
88	    : count * BASE_PREMIUMS[type];
89	
90	const countByType = (items: Item[]): Map<string, number> =>
91	  items.reduce(
92	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
93	    new Map<string, number>(),
94	  );
95	
96	const policyBasePremium = (items: Item[]): number =>
97	  [...countByType(items)].reduce(
98	    (total, [type, count]) => total + basePremiumForItemType(type, count),
99	    0,
100	  );
101	
102	const CURSE_SURCHARGE_RATE = 0.5;
103	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
104	const HIGH_ENCHANTMENT_LEVEL = 5;
105	
106	const isHighlyEnchanted = (item: Item): boolean =>
107	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
108	
109	interface RiskFactor {
110	  applies: (item: Item) => boolean;
111	  rate: number;
112	}
113	
114	const RISK_FACTORS: RiskFactor[] = [
115	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
116	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
117	];
118	
119	const itemRiskSurcharge = (item: Item): number =>
120	  RISK_FACTORS.reduce(
121	    (total, { applies, rate }) =>
122	      applies(item) ? total + BASE_PREMIUMS[item.type] * rate : total,
123	    0,
124	  );
125	
126	const totalRiskSurcharges = (items: Item[]): number =>
127	  items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
128	
129	const LOYALTY_DISCOUNT_RATE = -0.2;
130	const LOYALTY_YEARS = 2;
131	
132	const isLoyal = (customer: Customer): boolean =>
133	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
134	
135	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
136	
137	/** A quote in the context of the customer's history with the MHPCO. */
138	interface Contract {
139	  customer: Customer;
140	  /** Zero-based ordinal of this quote among the customer's quotes. */
141	  ordinal: number;
142	}
143	
144	const isFollowUpContract = (contract: Contract): boolean =>
145	  contract.ordinal > 0;
146	
147	/**
148	 * Policy-wide modifiers are charged on the policy base premium, unlike the
149	 * item-specific RISK_FACTORS which are charged on each affected item's own
150	 * base premium. Rates are signed: negative is a discount.
151	 */
152	interface PolicyFactor {
153	  applies: (contract: Contract) => boolean;
154	  rate: number;
155	}
156	
157	const POLICY_FACTORS: PolicyFactor[] = [
158	  {
159	    applies: ({ customer }) => isLoyal(customer),
160	    rate: LOYALTY_DISCOUNT_RATE,
161	  },
162	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
163	  {
164	    applies: isFollowUpContract,
165	    rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
166	  },
167	];
168	
169	const totalPolicyAdjustments = (
170	  policyBase: number,
171	  contract: Contract,
172	): number =>
173	  POLICY_FACTORS.reduce(
174	    (total, { applies, rate }) =>
175	      applies(contract) ? total + policyBase * rate : total,
176	    0,
177	  );
178	
179	const quotePremium = (items: Item[], contract: Contract): number => {
180	  const policyBase = policyBasePremium(items);
181	  return roundPremiumInMHPCOsFavour(
182	    policyBase +
183	      totalRiskSurcharges(items) +
184	      totalPolicyAdjustments(policyBase, contract) +
185	      PROCESSING_FEE,
186	  );
187	};
188	
189	const INSURANCE_VALUES: Record<string, number> = {
190	  sword: 1000,
191	  amulet: 600,
192	  staff: 800,
193	  potion: 400,
194	  rune: 250,
195	  moonstone: 250,
196	};
197	
198	const DEDUCTIBLE_PER_DAMAGE = 100;
199	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
200	
201	const insuranceSum = (items: Item[]): number =>
202	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
203	
204	const payoutCap = (items: Item[]): number =>
205	  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
206	
207	/**
208	 * Distinct from the premium side's HIGH_ENCHANTMENT_LEVEL of 5: the payout
209	 * rule and the surcharge rule share a shape but not a threshold.
210	 */
211	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
212	const HALF_REIMBURSEMENT_RATE = 0.5;
213	const FULL_REIMBURSEMENT_RATE = 1;
214	
215	/**
216	 * The share of a damage amount the MHPCO reimburses, before the deductible.
217	 * Damage to a heavily enchanted item is reimbursed at half.
218	 */
219	const reimbursementRate = (item: Item): number =>
220	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
221	    ? HALF_REIMBURSEMENT_RATE
222	    : FULL_REIMBURSEMENT_RATE;
223	
224	const damagePayout = (damage: Damage, policyItems: Item[]): number => {
225	  const damagedItem = policyItems.find(
226	    (item) => item.type === damage.itemType,
227	  ) as Item;
228	  return damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
229	};
230	
231	/**
232	 * A claim is settled in full or not at all: damaging more items of a type than
233	 * the policy covers rejects the whole claim.
234	 */
235	const rejectOverclaimedTypes = (
236	  damages: Damage[],
237	  policyItems: Item[],
238	): void => {
239	  const covered = countByType(policyItems);
240	  for (const [type, claimed] of countByType(
241	    damages.map((damage) => ({ type: damage.itemType })),
242	  )) {
243	    if (claimed > (covered.get(type) ?? 0)) {
244	      throw new Error(
245	        `claim covers ${claimed} ${type} damages but the policy insures ${covered.get(type) ?? 0}`,
246	      );
247	    }
248	  }
249	};
250	
251	const claimResult = (
252	  step: ClaimStep,
253	  policyItems: Item[],
254	  capAlreadyUsed: number,
255	): ClaimResult => {
256	  rejectOverclaimedTypes(step.incident.damages, policyItems);
257	  const claimed = roundPayoutInMHPCOsFavour(
258	    step.incident.damages.reduce(
259	      (total, damage) => total + damagePayout(damage, policyItems),
260	      0,
261	    ),
262	  );
263	  // The cap covers the policy's whole lifetime, so a claim can only draw on
264	  // what earlier claims against the same policy have left.
265	  const capLeft = payoutCap(policyItems) - capAlreadyUsed;
266	  const payout = Math.min(claimed, capLeft);
267	  return { payout, remainingCap: capLeft - payout };
268	};
269	
270	/**
271	 * The items covered by the policy a claim is filed against. A claim's `policy`
272	 * is the index of the quote step that established the policy.
273	 *
274	 * Assumes that step is in fact a quote; no test yet covers a claim pointing at
275	 * a non-quote step, so the assumption is asserted rather than checked.
276	 */
277	const policyItemsFor = (steps: Step[], claim: ClaimStep): Item[] =>
278	  (steps[claim.policy] as QuoteStep).items;
279	
280	/**
281	 * What running the steps so far has established. Steps are settled in order and
282	 * each one reads this, so it carries everything a later step needs to know
283	 * about its predecessors.
284	 */
285	interface Ledger {
286	  /** Results of the steps settled so far, in step order. */
287	  results: StepResult[];
288	  /** Payout drawn against each policy so far, keyed by its quote step's index. */
289	  capUsedByPolicy: ReadonlyMap<number, number>;
290	  /** How many quotes have been settled: the next quote's contract ordinal. */
291	  quotesSoFar: number;
292	}
293	
294	const EMPTY_LEDGER: Ledger = {
295	  results: [],
296	  capUsedByPolicy: new Map(),
297	  quotesSoFar: 0,
298	};
299	
300	const settleQuote = (
301	  step: QuoteStep,
302	  customer: Customer,
303	  ledger: Ledger,
304	): Ledger => ({
305	  ...ledger,
306	  results: [
307	    ...ledger.results,
308	    {
309	      premium: quotePremium(step.items, {
310	        customer,
311	        ordinal: ledger.quotesSoFar,
312	      }),
313	    },
314	  ],
315	  quotesSoFar: ledger.quotesSoFar + 1,
316	});
317	
318	const settleClaim = (
319	  step: ClaimStep,
320	  steps: Step[],
321	  ledger: Ledger,
322	): Ledger => {
323	  const capUsed = ledger.capUsedByPolicy.get(step.policy) ?? 0;
324	  const result = claimResult(step, policyItemsFor(steps, step), capUsed);
325	  return {
326	    ...ledger,
327	    results: [...ledger.results, result],
328	    capUsedByPolicy: new Map(ledger.capUsedByPolicy).set(
329	      step.policy,
330	      capUsed + result.payout,
331	    ),
332	  };
333	};
334	
335	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
336	  const { results } = steps.reduce(
337	    (ledger, step) =>
338	      step.op === "claim"
339	        ? settleClaim(step, steps, ledger)
340	        : settleQuote(step, customer, ledger),
341	    EMPTY_LEDGER,
342	  );
343	  return { results };
344	};
